<script setup lang="ts">
const config=useRuntimeConfig();const demoEnabled=Boolean(config.public.editorialDemo)
if (!demoEnabled) throw createError({ statusCode: 404, statusMessage: 'Página não encontrada' })
const session=useState<{token:string;name:string;role:string;authorId:string}|null>('editorial-session',()=>null)
const credentials=reactive({username:'',password:''});const loginError=ref('');const loading=ref(false);const rows=ref<any[]>([]);const selected=ref('all');const notice=ref('')
const draft=reactive({title:'',excerpt:'',category:'cidade',body:''})
const editing=ref<string|null>(null)
const states=[{id:'draft',label:'Rascunhos'},{id:'review',label:'Em revisão'},{id:'returned',label:'Devolvidos'},{id:'approved',label:'Aprovados'},{id:'published',label:'Publicados'},{id:'unpublished',label:'Retirados do ar'},{id:'archived',label:'Arquivados'}]
async function login(){loading.value=true;loginError.value='';try{const result:any=await $fetch(`${String(config.public.apiBase).replace(/\/$/,'')}/editor/login`,{method:'POST',body:credentials});session.value={token:result.token,name:result.name,role:result.role,authorId:result.authorId};credentials.password='';await loadRows()}catch{loginError.value='Não foi possível entrar. Confira o usuário e a senha da demonstração local.'}finally{loading.value=false}}
async function request(path:string,method='GET',body?:unknown){if(!session.value)throw new Error('Sessão encerrada');return await $fetch(`${String(config.public.apiBase).replace(/\/$/,'')}${path}`,{method:method as any,body:body as any,headers:{Authorization:`Bearer ${session.value.token}`}})}
async function loadRows(){try{const result:any=await request('/editor/articles');rows.value=result.articles||[]}catch{session.value=null}}
function startEdit(article:any){editing.value=article.id;Object.assign(draft,{title:article.title,excerpt:article.excerpt,category:article.category,body:(article.body||[]).join('\n\n')});document.getElementById('nova-pauta')?.scrollIntoView({behavior:'smooth',block:'start'})}
function stopEdit(){editing.value=null;Object.assign(draft,{title:'',excerpt:'',category:'cidade',body:''})}
async function saveDraft(){if(!draft.title.trim()||!draft.excerpt.trim()||!draft.body.trim())return;if(editing.value)await request(`/editor/articles/${editing.value}/edit`,'POST',draft);else await request('/editor/articles','POST',draft);notice.value=editing.value?'Nova versão salva no histórico editorial.':'Rascunho salvo.';stopEdit();await loadRows()}
async function act(article:any,action:string,body?:unknown){await request(`/editor/articles/${article.id}/${action}`,'POST',body);notice.value='Etapa registrada no histórico editorial.';await loadRows()}
async function logout(){try{await request('/editor/logout','POST')}catch{}session.value=null;rows.value=[]}
const visibleRows=computed(()=>rows.value.filter(item=>selected.value==='all'||item.status===selected.value))
onMounted(()=>{if(session.value)loadRows()})
useSeoMeta({title:'Área editorial',robots:'noindex,nofollow'})
</script>

<template>
  <div class="container newsroom">
    <header class="page-intro"><span class="eyebrow">Pé de Prosa · Redação</span><h1>Área editorial</h1><p>Organização de pauta, revisão e publicação.</p></header>
    <div v-if="!demoEnabled" class="editorial-off"><h2>Área da redação</h2><p>O acesso ao painel editorial está disponível na instalação local de demonstração.</p><NuxtLink class="button secondary" to="/">Voltar à publicação</NuxtLink></div>
    <section v-else-if="!session" class="login-panel"><div><span class="eyebrow">Acesso de demonstração local</span><h2>Entre na redação</h2><p>Escolha um perfil editorial para acompanhar o fluxo de uma pauta.</p></div><form @submit.prevent="login"><div class="form-field"><label for="username">Usuário</label><input id="username" v-model="credentials.username" autocomplete="username" required></div><div class="form-field"><label for="password">Senha</label><input id="password" v-model="credentials.password" type="password" autocomplete="current-password" required></div><p v-if="loginError" class="error-text" role="alert">{{ loginError }}</p><button class="button" :disabled="loading">{{ loading?'Entrando…':'Acessar painel' }}</button></form></section>
    <section v-else class="dashboard"><div class="dashboard-head"><div><span class="eyebrow">{{ session.role }}</span><h2>Bom trabalho, {{ session.name }}</h2></div><button class="button secondary" @click="logout">Sair</button></div><div v-if="notice" class="notice" role="status">{{ notice }}</div><div class="status-cards"><button v-for="state in states" :key="state.id" :class="{active:selected===state.id}" @click="selected=state.id"><strong>{{ rows.filter(row=>row.status===state.id).length }}</strong><span>{{ state.label }}</span></button><button :class="{active:selected==='all'}" @click="selected='all'"><strong>{{ rows.length }}</strong><span>Todos</span></button></div>
      <div v-if="session.role==='autor'" id="nova-pauta" class="new-draft"><div class="draft-heading"><h3>{{ editing?'Editar texto':'Novo rascunho' }}</h3><button v-if="editing" type="button" @click="stopEdit">Cancelar edição</button></div><form @submit.prevent="saveDraft"><div class="form-field"><label for="title">Título de trabalho</label><input id="title" v-model="draft.title" maxlength="140" required></div><div class="form-field"><label for="excerpt">Resumo</label><textarea id="excerpt" v-model="draft.excerpt" maxlength="300" required></textarea></div><div class="form-field"><label for="category">Editoria</label><select id="category" v-model="draft.category"><option v-for="category in ['cidade','cultura','cotidiano','ideias','trabalho','natureza']" :key="category" :value="category">{{ category }}</option></select></div><div class="form-field"><label for="body">Texto</label><textarea id="body" v-model="draft.body" required></textarea><small>Separe os parágrafos com uma linha em branco.</small></div><button class="button">{{ editing?'Salvar nova versão':'Salvar rascunho' }}</button></form></div>
      <div class="story-list"><div class="list-heading"><h3>{{ states.find(state=>state.id===selected)?.label || 'Todos os textos' }}</h3><button @click="loadRows">Atualizar lista</button></div><article v-for="article in visibleRows" :key="article.id" class="story-row"><div><span class="eyebrow">{{ article.category_name }} · {{ article.status }}</span><h4>{{ article.title }}</h4><p>{{ article.excerpt }}</p><div class="metadata"><span>{{ article.author_name }}</span><span class="dot">•</span><span>{{ article.updated_at }}</span></div><ul v-if="article.events?.length" class="event-history"><li v-for="event in article.events" :key="event.created_at+event.action"><strong>{{ event.action }}</strong> · {{ event.actor_name }} <span>{{ event.created_at }}</span><small v-if="event.note">{{ event.note }}</small></li></ul></div><div class="row-actions"><button v-if="session.role==='autor' && article.author_id===session.authorId && ['draft','returned'].includes(article.status)" @click="startEdit(article)">Editar texto</button><button v-if="session.role==='autor' && article.author_id===session.authorId && ['draft','returned'].includes(article.status)" @click="act(article,'submit')">Enviar à revisão</button><button v-if="session.role==='revisor' && article.status==='review'" @click="act(article,'review',{result:'approved',note:'Texto aprovado para publicação.'})">Aprovar</button><button v-if="session.role==='revisor' && article.status==='review'" @click="act(article,'review',{result:'returned',note:'Revisar clareza e contexto antes da próxima leitura.'})">Devolver</button><button v-if="session.role==='editor' && ['approved','unpublished'].includes(article.status)" @click="act(article,'publish')">{{ article.status==='unpublished'?'Republicar':'Publicar' }}</button><button v-if="session.role==='editor' && article.status==='published'" @click="act(article,'unpublish')">Retirar do ar</button><button v-if="session.role==='editor' && ['published','unpublished'].includes(article.status)" @click="act(article,'archive')">Arquivar</button></div></article><p v-if="!visibleRows.length" class="empty-state">Nenhum texto nesta etapa.</p></div>
    </section>
  </div>
</template>

<style scoped>.newsroom{padding-bottom:2rem}.editorial-off,.login-panel{max-width:950px;margin:2rem auto;padding:2rem;background:var(--white);box-shadow:var(--shadow)}.login-panel{display:grid;grid-template-columns:1fr 1fr;gap:2rem;align-items:center}.login-panel h2,.dashboard-head h2{font:600 2rem var(--serif);margin:.3rem 0}.login-panel form{max-width:420px}.dashboard{padding:1.5rem 0}.dashboard-head{display:flex;justify-content:space-between;align-items:center}.status-cards{display:grid;grid-template-columns:repeat(7,1fr);gap:.5rem;margin:1.2rem 0 2rem}.status-cards button{background:var(--white);border:1px solid var(--line);padding:.8rem .5rem;text-align:left;cursor:pointer;color:var(--ink)}.status-cards button.active{border-color:var(--forest);box-shadow:inset 0 -3px var(--forest)}.status-cards strong,.status-cards span{display:block}.status-cards strong{font:600 1.5rem var(--serif)}.status-cards span{font-size:.68rem;color:var(--muted)}.new-draft{background:#e9e4d8;padding:1.4rem;max-width:850px;margin:2rem 0}.new-draft h3,.story-list h3{font:600 1.45rem var(--serif);margin:.2rem 0 1rem}.draft-heading{display:flex;justify-content:space-between;align-items:center}.draft-heading button{border:0;background:none;color:var(--forest);text-decoration:underline;cursor:pointer}.new-draft form{display:grid;grid-template-columns:1fr 1fr;gap:0 1rem}.new-draft .form-field:nth-child(2),.new-draft .form-field:nth-child(4){grid-column:1/-1}.new-draft button{justify-self:start}.list-heading{display:flex;justify-content:space-between;align-items:center}.list-heading button{border:0;background:none;color:var(--forest);font-weight:700;cursor:pointer}.story-row{display:flex;justify-content:space-between;gap:1rem;padding:1.1rem 0;border-top:1px solid var(--line)}.story-row h4{font:600 1.25rem var(--serif);margin:.3rem 0}.story-row p{margin:.2rem 0 .5rem;color:var(--muted);font-size:.88rem}.event-history{margin:.8rem 0 0;padding-left:1.2rem;color:var(--muted);font-size:.75rem}.event-history li{padding:.2rem 0}.event-history small,.event-history span{display:block}.row-actions{display:flex;flex-direction:column;gap:.4rem;justify-content:center;min-width:130px}.row-actions button{padding:.5rem .6rem;background:var(--white);color:var(--forest);border:1px solid var(--line);font-size:.72rem;font-weight:700;cursor:pointer}.row-actions button:hover{border-color:var(--forest)}@media(max-width:800px){.status-cards{grid-template-columns:repeat(4,1fr)}}@media(max-width:600px){.login-panel{grid-template-columns:1fr;padding:1.3rem}.status-cards{grid-template-columns:repeat(2,1fr)}.new-draft form{grid-template-columns:1fr}.new-draft .form-field{grid-column:1/-1}.story-row{flex-direction:column}.row-actions{flex-direction:row;flex-wrap:wrap}.dashboard-head{align-items:start}.dashboard-head .button{padding:.6rem}}
</style>
